import { useState, useMemo, type FormEvent } from 'react';
import {
  JxInputField,
  JxSelect,
  JxSwitch,
  JxButton,
  JxToast,
} from '@jinx-ui/react';

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const ROLE_OPTIONS = [
  { value: 'admin', label: 'Администратор' },
  { value: 'editor', label: 'Редактор' },
  { value: 'viewer', label: 'Наблюдатель' },
];

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [role, setRole] = useState('editor');
  const [notify, setNotify] = useState(true);
  const [submitted, setSubmitted] = useState(false);

  const emailError = useMemo(() => {
    if (!email) return undefined;
    return EMAIL_PATTERN.test(email) ? undefined : 'Введите почту в формате name@example.com';
  }, [email]);

  const canSubmit = email.length > 0 && !emailError;

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!canSubmit) return;
    setSubmitted(true);
  };

  return (
    <div style={{ maxWidth: 420, display: 'flex', flexDirection: 'column', gap: 16 }}>
      {submitted && (
        <JxToast
          variant="success"
          title="Приглашение отправлено"
          message={`Мы пригласили ${email} в команду.`}
          onClose={() => setSubmitted(false)}
        />
      )}

      <form
        onSubmit={handleSubmit}
        style={{
          display: 'flex',
          flexDirection: 'column',
          gap: 16,
          padding: 20,
          background: 'var(--jx-surface)',
          border: '1px solid var(--jx-border)',
          borderRadius: 'var(--jx-r-lg)',
        }}
      >
        <JxInputField
          label="Электронная почта"
          type="email"
          required
          placeholder="name@example.com"
          value={email}
          onChange={(event) => setEmail(event.target.value)}
          errorText={emailError}
          helperText="На эту почту придёт приглашение в команду"
        />

        <JxSelect
          label="Роль"
          options={ROLE_OPTIONS}
          value={role}
          onValueChange={setRole}
        />

        <JxSwitch
          label="Отправить уведомление"
          checked={notify}
          onChange={(event) => setNotify(event.target.checked)}
        />

        <JxButton type="submit" variant="primary" disabled={!canSubmit}>
          Отправить приглашение
        </JxButton>
      </form>
    </div>
  );
}

